<?php require_once __DIR__.'/db.php'; require_once __DIR__.'/../includes/auth.php'; requireAdmin(); header('Content-Type: application/json; charset=UTF-8'); $m=$_SERVER['REQUEST_METHOD']; if($m==='GET'){ $r=$conn->query("SELECT id,name,email,status,created_at FROM users WHERE role='employee' ORDER BY id DESC");$a=[];while($r&&$x=$r->fetch_assoc())$a[]=$x;echo json_encode(['success'=>true,'items'=>$a],JSON_UNESCAPED_UNICODE);exit;} if($m==='POST'){ $d=json_decode(file_get_contents('php://input'),true)??[];$name=trim($d['name']??'');$email=strtolower(trim($d['email']??''));$password=$d['password']??''; if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){http_response_code(422);echo json_encode(['success'=>false,'message'=>'بيانات الموظف غير صحيحة'],JSON_UNESCAPED_UNICODE);exit;} $hash=password_hash($password,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,'employee','active')");$s->bind_param('sss',$name,$email,$hash);if(!$s->execute()){http_response_code(409);echo json_encode(['success'=>false,'message'=>'البريد مستخدم مسبقًا'],JSON_UNESCAPED_UNICODE);exit;}echo json_encode(['success'=>true],JSON_UNESCAPED_UNICODE);exit;} ?>